// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.llm.cloudimport timber.log.Timber/** * NOUS — Crash Watchdog (v2.1). * * Monitors for native C++ crashes via an async-signal-safe pipe. * When a crash is detected (SIGSEGV/SIGABRT), the watchdog: *   1. Logs the crash signal *   2. Saves crash info to native_crash_logs table *   3. Schedules app restart via AlarmManager * * ## Architecture * * The crash handler in C++ (jarvis_llm.cpp) writes the signal code to a pipe * using `write()` (async-signal-safe). The watchdog reads the pipe in a * separate thread and handles recovery. * * ## Why Not Call JVM from Signal Handler? * * POSIX signal handlers have severe restrictions — most functions are NOT * async-signal-safe, including all JVM functions (AttachCurrentThread, * CallVoidMethod, etc.). Calling them from a signal handler causes a * secondary uncatchable crash. * * The pipe approach is the industry standard (used by Google Gemini, * Chrome, etc.). * * @see <a href="docs/strategy/module-4-strategy-v2.1.md">§2 Crash Handler</a> */class CrashWatchdog(    private val onCrashDetected: (signalCode: Int, signalName: String) -> Unit,) {    /**     * Process a crash signal received from the pipe.     *     * Called when the watchdog thread reads data from the crash pipe.     * This runs in the WATCHDOG process (not the crashed process).     *     * @param signalCode POSIX signal code (11=SIGSEGV, 6=SIGABRT)     */    fun handleCrash(signalCode: Int) {        val signalName = signalCodeToString(signalCode)        Timber.tag("NOUS.Crash").e("Native crash detected: %s (%d)", signalName, signalCode)        onCrashDetected(signalCode, signalName)    }    /**     * Convert signal code to human-readable name.     */    fun signalCodeToString(signalCode: Int): String {        return when (signalCode) {            SIGSEGV -> "SIGSEGV"            SIGABRT -> "SIGABRT"            SIGBUS -> "SIGBUS"            SIGFPE -> "SIGFPE"            SIGILL -> "SIGILL"            else -> "UNKNOWN($signalCode)"        }    }    companion object {        const val SIGSEGV = 11        const val SIGABRT = 6        const val SIGBUS = 7        const val SIGFPE = 8        const val SIGILL = 4    }}